<script>
document.querySelectorAll('[data-profile-tab]').forEach(function(tab){tab.addEventListener('click',function(){var target=tab.dataset.profileTab;document.querySelectorAll('[data-profile-tab]').forEach(function(item){item.classList.toggle('active',item===tab)});document.querySelectorAll('[data-profile-section]').forEach(function(section){section.hidden=section.dataset.profileSection!==target})})});
document.querySelector('[data-profile-photo]')?.addEventListener('change',function(){var file=this.files?.[0];if(!file)return;var reader=new FileReader();reader.onload=function(){document.querySelectorAll('[data-profile-avatar]').forEach(function(avatar){avatar.innerHTML='<img src="'+reader.result+'" alt="Aperçu de la photo de profil">'})};reader.readAsDataURL(file)});
</script>
